 if(!Array.isArray(instance.args)||(instance.args.length!==(rule.instanceArgsNum??rule.argsNum)&&!(instance.id===534&&instance.args.length===0)&&!(instance.id===1056&&instance.args.length===2&&instance.args[1]===2))||instance.args.some(x=>!Number.isInteger(x)))return {issue:`效果 ${instance.id} 实例参数无效`,operations:[]};
 if(rule.direct){try{rule.validate(instance.args);operations.push({effectId:instance.id,index,phase:rule.phase,params:instance.args.slice(),sourceArgs:instance.args.slice(),deferred:rule.deferred});}catch(e){return {issue:`效果 ${instance.id}：${e.message}`,operations:[]};}continue;}
 const args=instance.args.slice();if([4,5].includes(instance.id)){const labels=['攻击','防御','特攻','特防','速度','命中'];if(!labels[args[0]])return {issue:'能力参数无效',operations:[]};args[0]=labels[args[0]];}
