'use strict';
const {test}=require('node:test');
const assert=require('node:assert/strict');
const H=require('./helpers/3577-battle.cjs');
const {source,keys,key,IDLE,WAIT,HIT,FEAR,make,turn,wait,timer,allStages,pick,seedCase}=H;
const hp=o=>o.fighters.map(f=>f.hp);

test('3577 来源快照与缓存的27招、40实例及魂印原文参数逐项一致',()=>{
  for(const m of source.moves){const raw=require('../research/seerapi-cache/3577/skill-'+m.id+'.json');
    assert.equal(m.hash,raw.hash);assert.equal(m.name,raw.name);assert.equal(m.power,raw.power);assert.equal(m.pp,raw.max_pp);assert.equal(m.priority,raw.priority);assert.equal(m.alwaysHit,raw.must_hit);
    assert.deepEqual(m.effectInstances,raw.skill_effect.map(e=>({id:e.effect.id,args:e.args})));
    for(const x of m.effectInstances){const meta=require('../research/seerapi-cache/3577/skill_effect_type-'+x.id+'.json'),saved=source.effects.find(e=>e.id===x.id);assert.equal(saved.template,meta.info);assert.equal(saved.revision,'seerapi:'+meta.hash);assert.equal(x.args.length,meta.args_num);}
  }
