const {test}=require('node:test');
const assert=require('node:assert/strict');
const E=require('../dist/engine.js');
const effects=require('../dist/effect-registry.js');
const source=require('../data/species/3577.json').snapshot;
const soul=E.SOULS.registry[881];
function fighter(hp=700){return {hp,stats:{maxHp:1000},soulState:{},stages:{atk:0,def:0,spa:0,spd:0,spe:0,acc:0},ailments:{},effects:{},counts:{},side:0,moves:['a','b'],pp:{a:3,b:2}};}
function context(a,t,random=()=>0){const events=[];return {a,t,round:1,m:{kind:'physical',name:'测试技能'},random,emit:x=>events.push(x),name:f=>f===a?'A':'B',on:(f,k)=>!!f.effects[k]&&f.effects[k].start<=1&&f.effects[k].end>=1,heal:(f,n)=>{f.hp=Math.min(f.stats.maxHp,f.hp+Math.floor(n));},hurt:(f,n)=>{const v=Math.min(f.hp,Math.floor(n));f.hp-=v;return v;},stage:(f,n,keys)=>{for(const k of keys??Object.keys(f.stages))f.stages[k]=Math.max(-6,Math.min(6,f.stages[k]+n));},boost:(f,n)=>{for(const k of Object.keys(f.stages))f.stages[k]+=n;},timed:(f,k,n,d,start=1)=>{f.effects[k]={start,end:start+n-1,...d};},clear:(f)=>{const had=Object.keys(f.effects).length>0;f.effects={};return had;},clearBoost:(f)=>{const had=Object.values(f.stages).some(n=>n>0);for(const k of Object.keys(f.stages))if(f.stages[k]>0)f.stages[k]=0;return had;},ailment:(f,k)=>{f.ailments[k]=2;return true;},events};}
function rule(id){const move=source.moves.find(m=>m.effectIds.includes(id));return effects.compileInstances(move.effectInstances.filter(x=>x.id===id),source.effects);}

test('3577 快照、魂印881、光战斗属性和第五技能来源通过核对',()=>{assert.equal(source.souls[0].id,881);assert.equal(source.souls[0].hash,soul.sourceHash);assert.deepEqual(source.typeChart.aliases['光战斗'],['光','战斗']);assert.equal(source.moves.filter(m=>m.fifth).length,1);});
test('3577 效果620登记三回合暴击率提升，效果1258按伤害阈值消费异常免疫',()=>{const a=fighter(),t=fighter();a.side=0;t.side=1;let c=context(a,t);effects.run('afterHit',rule(620).operations,c);assert.equal(a.effects['暴击概率增加'].chance,5/16);assert.equal(a.effects['暴击概率增加'].end,3);c.dealt=281;effects.run('afterAttack',rule(1258).operations,c);assert.equal(a.counts.immune,1);});
test('3577 效果1297消回合成功疲惫，失败按最大体力三分之一吸取',()=>{const a=fighter(),t=fighter();a.side=0;t.side=1;t.effects.foo={start:1,end:2};let c=context(a,t);effects.run('afterHit',rule(1297).operations,c);assert.equal(t.ailments['疲惫'],2);const b=fighter(500),u=fighter();b.side=0;u.side=1;c=context(b,u);effects.run('afterHit',rule(1297).operations,c);assert.equal(u.hp,367);assert.equal(b.hp,833);});
test('3577 效果1188建立三回合受击反应，1255独立用招失明失败追加百分比伤害',()=>{const a=fighter(),t=fighter();a.side=0;t.side=1;let c=context(a,t);effects.run('afterHit',rule(1188).operations,c);assert.equal(a.effects['光惩持续'].end,3);assert.equal(a.effects['光惩持续'].fatigue,'疲惫');const H=require('./helpers/3577-battle.cjs'),s=H.make(H.pick(1255)[0],{targetHp:700,bStats:{maxHp:1000}});H.timer(s,1,'免异常');const o=H.turn(s);assert.equal(o.fighters[1].hp,367);assert.equal(o.fighters[0].soulId,null);});
test('3577 效果1040仅未击败时疲惫或全强，击败不得执行延期1128',()=>{const a=fighter(),t=fighter();a.side=0;t.side=1;let c=context(a,t,()=>0);c.dealt=100;c.t.hp=500;effects.run('afterAttack',rule(1040).operations,c);assert.equal(t.ailments['疲惫'],2);const b=fighter(),u=fighter();b.side=0;u.side=1;c=context(b,u,()=>.99);c.dealt=200;u.hp=0;effects.run('afterAttack',rule(1040).operations,c);assert.equal(u.counts.nextAttackInvalid,undefined);assert.deepEqual(Object.values(b.stages),[0,0,0,0,0,0]);u.hp=500;effects.run('afterAttack',rule(1040).operations,c);assert.deepEqual(Object.values(b.stages),[1,1,1,1,1,1]);});
test('魂印881攻击高于280追加三分之一并封属性，低于280吸取并令下回合攻击必暴，首次致死保留1点',()=>{const a=fighter(700),t=fighter();a.side=0;t.side=1;let c=context(a,t);c.dealt=281;soul.hooks.afterAttack({...c,dealt:281});assert.equal(t.hp,367);assert.ok(t.effects.statusBlock);const b=fighter(700),u=fighter();b.side=0;u.side=1;c=context(b,u);soul.hooks.afterAttack({...c,dealt:100});assert.equal(b.effects['必定暴击'].start,2);assert.equal(b.hp,1000);});

